feature-dme-qty.translation:
Instrução: Adicionar suporte a quantidade por DME no pack. O array selectedDmeIds (plano) vira selectedDmes (objetos {id, qty}). Um painel abaixo da grade mostra os DMEs selecionados com stepper −/+. O formato dme_ids no BD passa a ser [{id, qty}, ...]. A loja exibe badge de quantidade nos cards do modal. Quatro arquivos: admin/class-admin-page.php, admin/admin.js, public/store.js, assets/style.css.

=== 1. admin/class-admin-page.php — adicionar painel de selecionados ===

Em render_crud_mode(), localizar a div que contém o feed de DMEs. Essa div tem id cc-dme-list. Localizar o fechamento do container pai que envolve #cc-dme-list (o div que inclui a label, o search e o dme-list). Após o </div> de fechamento desse container, adicionar:

    <div id="cc-selected-dmes-panel" class="cc-selected-dmes-panel">
        <p class="cc-selected-empty">Nenhum DME selecionado.</p>
    </div>

=== 2. admin/admin.js — helpers globais ===

Após:
    var allFeedItems   = [];

Adicionar as três funções helper:

    function normalizeDmeIds(dmeIds) {
        return (dmeIds || []).map(function (item) {
            if (typeof item === 'object' && item !== null && item.id) {
                return { id: String(item.id), qty: parseInt(item.qty) || 1 };
            }
            return { id: String(item), qty: 1 };
        });
    }

    function dmeCount(dmeIds) {
        if (!dmeIds || !dmeIds.length) return 0;
        return dmeIds.reduce(function (sum, d) {
            return sum + (typeof d === 'object' ? (parseInt(d.qty) || 1) : 1);
        }, 0);
    }

    function escHtml(s) {
        return String(s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
    }

=== 3. admin/admin.js — substituir var selectedDmeIds ===

Localizar:
    var selectedDmeIds = [];

Substituir por:
    var selectedDmes = [];

=== 4. admin/admin.js — cancel: resetar selectedDmes ===

Localizar:
    selectedDmeIds = [];
(dentro do handler $cancel.on('click', ...))

Substituir por:
    selectedDmes = [];
    renderSelectedPanel();

=== 5. admin/admin.js — save: validação e payload ===

Localizar:
    if (!selectedDmeIds.length) { alert('Selecione ao menos 1 DME.'); return; }

Substituir por:
    if (!selectedDmes.length) { alert('Selecione ao menos 1 DME.'); return; }

Localizar:
    dme_ids: selectedDmeIds.slice(),

Substituir por:
    dme_ids: selectedDmes.map(function (d) { return { id: d.id, qty: d.qty }; }),

=== 6. admin/admin.js — após save bem-sucedido: limpar selectedDmes ===

Localizar (dentro do then de sucesso do save):
    editingId = null; selectedDmeIds = [];

Substituir por:
    editingId = null; selectedDmes = []; renderSelectedPanel();

=== 7. admin/admin.js — render dos cards: usar selectedDmes ===

Localizar:
    var checked = selectedDmeIds.indexOf(id) !== -1;

Substituir por:
    var checked = selectedDmes.some(function (d) { return d.id === id; });

=== 8. admin/admin.js — card click handler: usar selectedDmes ===

Localizar o bloco completo:
    $dmeList.on('click', '.cc-admin-dme-card', function () {
        var id = String($(this).data('dme-id'));
        if ($(this).hasClass('is-selected')) {
            selectedDmeIds = selectedDmeIds.filter(function (v) { return v !== id; });
            $(this).removeClass('is-selected');
        } else {
            if (selectedDmeIds.indexOf(id) === -1) selectedDmeIds.push(id);
            $(this).addClass('is-selected');
        }
        updateSelectedBadge();
    });

Substituir por:
    $dmeList.on('click', '.cc-admin-dme-card', function () {
        var id  = String($(this).data('dme-id'));
        var idx = selectedDmes.findIndex(function (d) { return d.id === id; });
        if (idx !== -1) {
            selectedDmes.splice(idx, 1);
            $(this).removeClass('is-selected');
        } else {
            selectedDmes.push({ id: id, qty: 1 });
            $(this).addClass('is-selected');
        }
        updateSelectedBadge();
        renderSelectedPanel();
    });

    $(document).on('click', '.cc-qty-minus', function () {
        var id   = String($(this).data('id'));
        var item = selectedDmes.find(function (d) { return d.id === id; });
        if (item && item.qty > 1) { item.qty--; renderSelectedPanel(); updateSelectedBadge(); }
    });

    $(document).on('click', '.cc-qty-plus', function () {
        var id   = String($(this).data('id'));
        var item = selectedDmes.find(function (d) { return d.id === id; });
        if (item) { item.qty++; renderSelectedPanel(); updateSelectedBadge(); }
    });

    $(document).on('click', '.cc-selected-dme-remove', function () {
        var id = String($(this).data('id'));
        selectedDmes = selectedDmes.filter(function (d) { return d.id !== id; });
        $dmeList.find('[data-dme-id="' + id + '"]').removeClass('is-selected');
        renderSelectedPanel();
        updateSelectedBadge();
    });

=== 9. admin/admin.js — updateSelectedBadge: usar dmeCount ===

Localizar:
    function updateSelectedBadge() {
        $('#cc-selected-count').text(
            selectedDmeIds.length ? selectedDmeIds.length + ' DME(s) selecionado(s)' : ''
        );
    }

Substituir por:
    function updateSelectedBadge() {
        var total = dmeCount(selectedDmes);
        $('#cc-selected-count').text(
            total ? total + ' DME(s) — ' + selectedDmes.length + ' tipo(s)' : ''
        );
    }

    function renderSelectedPanel() {
        var $panel = $('#cc-selected-dmes-panel');
        if (!$panel.length) return;
        $panel.empty();
        if (!selectedDmes.length) {
            $panel.html('<p class="cc-selected-empty">Nenhum DME selecionado.</p>');
            return;
        }
        selectedDmes.forEach(function (sel) {
            var dme  = allFeedItems.find(function (d) { return String(d.id) === sel.id; });
            var name = dme ? (dme.name || 'DME #' + sel.id) : 'DME #' + sel.id;
            var $item = $(
                '<div class="cc-selected-dme-item" data-id="' + sel.id + '">' +
                '  <span class="cc-selected-dme-name">' + escHtml(name) + '</span>' +
                '  <div class="cc-qty-stepper">' +
                '    <button type="button" class="cc-qty-btn cc-qty-minus" data-id="' + sel.id + '">−</button>' +
                '    <span class="cc-qty-value">' + sel.qty + '</span>' +
                '    <button type="button" class="cc-qty-btn cc-qty-plus" data-id="' + sel.id + '">+</button>' +
                '  </div>' +
                '  <button type="button" class="cc-selected-dme-remove" data-id="' + sel.id + '">×</button>' +
                '</div>'
            );
            $panel.append($item);
        });
    }

=== 10. admin/admin.js — edit: restaurar selectedDmes ===

Localizar:
    selectedDmeIds = (pack.dme_ids || []).map(String);

Substituir por:
    selectedDmes = normalizeDmeIds(pack.dme_ids || []);
    renderSelectedPanel();

=== 11. admin/admin.js — loadPacks: card count usa dmeCount ===

Localizar (dentro do forEach de loadPacks, na string HTML do card):
    (pack.dme_ids ? pack.dme_ids.length : 0) + ' DMEs'

Substituir por:
    dmeCount(pack.dme_ids || []) + ' DMEs'

=== 12. public/store.js — normalizeDmeIds helper ===

Antes da função buildSessionDescription(), adicionar:

    function normalizeDmeIds(dmeIds) {
        return (dmeIds || []).map(function (item) {
            if (typeof item === 'object' && item !== null && item.id) {
                return { id: String(item.id), qty: parseInt(item.qty) || 1 };
            }
            return { id: String(item), qty: 1 };
        });
    }

=== 13. public/store.js — openPackModal: usar dmeList normalizado ===

Dentro de openPackModal(), dentro de getFeed().then(function(items) { ... }), localizar:
    var ids   = (pack.dme_ids || []).map(String);
    var found = items.filter(function (d) { return ids.indexOf(String(d.id)) !== -1; });

Substituir por:
    var dmeList   = normalizeDmeIds(pack.dme_ids);
    var ids       = dmeList.map(function (d) { return d.id; });
    var found     = items.filter(function (d) { return ids.indexOf(String(d.id)) !== -1; });

Dentro do found.forEach (onde cada $item é montado e appended ao $cont), após $cont.append($item); adicionar:

    var dmeEntry = dmeList.find(function (d) { return d.id === String(dme.id); });
    if (dmeEntry && dmeEntry.qty > 1) {
        $item.css('position', 'relative').append(
            '<span class="cc-modal-qty-badge">\u00D7' + dmeEntry.qty + '</span>'
        );
    }

=== 14. public/store.js — buildSessionDescription: usar qty ===

Dentro de buildSessionDescription(), localizar o trecho:
    if (feedCache && pack.dme_ids && pack.dme_ids.length) {
        var ids = pack.dme_ids.map(String);
        feedCache.forEach(function (d) {
            if (ids.indexOf(String(d.id)) !== -1 && d.name) names.push(d.name);
        });
    }

Substituir por:
    if (feedCache && pack.dme_ids && pack.dme_ids.length) {
        var dmeList = normalizeDmeIds(pack.dme_ids);
        var ids     = dmeList.map(function (d) { return d.id; });
        feedCache.forEach(function (d) {
            if (ids.indexOf(String(d.id)) !== -1 && d.name) {
                var entry = dmeList.find(function (di) { return di.id === String(d.id); });
                var qty   = entry ? (entry.qty || 1) : 1;
                names.push(qty > 1 ? d.name + ' \u00D7' + qty : d.name);
            }
        });
    }

=== 15. assets/style.css — estilos do painel de selecionados e qty stepper ===

Ao final do arquivo, adicionar:

/* ==========================================================
   ADMIN — Painel de DMEs Selecionados + Qty Stepper
   ========================================================== */

.cc-selected-dmes-panel {
    margin-top: 10px;
    background: var(--cc-bg);
    border: 1px solid var(--cc-border);
    border-radius: var(--cc-r-sm);
    padding: 8px 10px;
    min-height: 46px;
    display: flex;
    flex-direction: column;
    gap: 6px;
    max-height: 260px;
    overflow-y: auto;
}

.cc-selected-empty {
    font-size: 12px;
    color: var(--cc-text-muted);
    margin: 0;
    text-align: center;
    padding: 8px 0;
}

.cc-selected-dme-item {
    display: flex;
    align-items: center;
    gap: 8px;
    background: var(--cc-surface);
    border: 1px solid var(--cc-border-mid);
    border-radius: var(--cc-r-xs);
    padding: 7px 10px;
    flex-shrink: 0;
}

.cc-selected-dme-name {
    flex: 1;
    font-size: 12px;
    color: var(--cc-text);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    min-width: 0;
}

.cc-qty-stepper {
    display: flex;
    align-items: center;
    gap: 5px;
    flex-shrink: 0;
}

.cc-qty-btn {
    width: 24px;
    height: 24px;
    border-radius: var(--cc-r-xs);
    border: 1px solid var(--cc-border-mid);
    background: var(--cc-raised);
    color: var(--cc-text);
    font-size: 15px;
    line-height: 1;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background var(--cc-t), border-color var(--cc-t), color var(--cc-t);
    padding: 0;
    font-weight: 700;
    flex-shrink: 0;
}
.cc-qty-btn:hover {
    background: var(--cc-accent);
    border-color: var(--cc-accent);
    color: #000;
}

.cc-qty-value {
    font-size: 13px;
    font-weight: 700;
    color: var(--cc-text);
    min-width: 20px;
    text-align: center;
}

.cc-selected-dme-remove {
    width: 20px;
    height: 20px;
    border-radius: 50%;
    border: 1px solid rgba(255,77,77,.3);
    background: rgba(255,77,77,.08);
    color: #ff6060;
    font-size: 13px;
    line-height: 1;
    cursor: pointer;
    display: flex;
    align-items: center;
    justify-content: center;
    transition: background var(--cc-t);
    padding: 0;
    flex-shrink: 0;
}
.cc-selected-dme-remove:hover {
    background: rgba(255,77,77,.3);
    color: #fff;
}

/* Badge de quantidade no modal da loja */
.cc-modal-qty-badge {
    position: absolute;
    top: 6px;
    right: 6px;
    background: var(--cc-accent);
    color: #000;
    font-size: 10px;
    font-weight: 900;
    border-radius: 20px;
    padding: 2px 6px;
    line-height: 1.4;
    pointer-events: none;
    z-index: 2;
}

Verificação: (1) render_crud_mode() contém div#cc-selected-dmes-panel após o container do dme-list. (2) Helpers normalizeDmeIds(), dmeCount() e escHtml() declarados em admin.js após allFeedItems. (3) var selectedDmes = [] substitui selectedDmeIds. (4) cancel reseta selectedDmes e chama renderSelectedPanel(). (5) save usa selectedDmes.length e envia dme_ids como [{id,qty},...]. (6) Render de cards usa selectedDmes.some(). (7) Card click usa findIndex + push/splice + renderSelectedPanel(). (8) Handlers de .cc-qty-minus, .cc-qty-plus, .cc-selected-dme-remove definidos. (9) renderSelectedPanel() definido dentro de initCrud(). (10) Edit handler usa normalizeDmeIds e chama renderSelectedPanel(). (11) loadPacks usa dmeCount(). (12) normalizeDmeIds definida em store.js. (13) openPackModal usa dmeList normalizado e appenda badge ×N. (14) buildSessionDescription usa qty para mostrar 'Name ×N'. (15) CSS adicionado ao final de style.css.
